create table if not exists places (
  id uuid primary key,
  slug text unique not null,
  name_zh text not null,
  name_ja text not null,
  category text not null,
  ward text not null,
  latitude numeric not null,
  longitude numeric not null,
  address text,
  nearest_station text,
  age_min int,
  age_max int,
  indoor boolean default false,
  rainy_day boolean default false,
  free_entry boolean default false,
  stroller_score int check (stroller_score between 1 and 5),
  diaper_score int check (diaper_score between 1 and 5),
  parking_score int check (parking_score between 1 and 5),
  play_score int check (play_score between 1 and 5),
  description text,
  tips text,
  image_url text,
  created_at timestamp default now(),
  updated_at timestamp default now()
);

create index if not exists places_category_idx on places(category);
create index if not exists places_ward_idx on places(ward);
create index if not exists places_age_idx on places(age_min, age_max);

insert into places (id, slug, name_zh, name_ja, category, ward, latitude, longitude, address, nearest_station, age_min, age_max, indoor, rainy_day, free_entry, stroller_score, diaper_score, parking_score, play_score, description, tips, image_url) values
('10000000-0000-4000-8000-000000000001', 'arakawa-nature-park', '荒川自然公园', '荒川自然公園', 'park', '荒川区', 35.7407, 139.7826, '東京都荒川区荒川8丁目25-3', '荒川二丁目站', 1, 10, false, false, true, 4, 3, 2, 5, '有大片绿地、交通园和水边步道，是荒川区经典放电点，适合半天慢慢玩。', '交通园很受欢迎，周末上午更从容；夏天记得带驱蚊和换洗衣物。', 'https://images.unsplash.com/photo-1519331379826-f10be5486c6f?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000002', 'shioiri-park', '汐入公园', '汐入公園', 'park', '荒川区', 35.7353, 139.8112, '東京都荒川区南千住8丁目13-1', '南千住站', 0, 10, false, false, true, 5, 3, 3, 5, '隅田川边的大型公园，视野开阔，草地、 playground 和散步路线都很适合亲子。', '婴儿车推行舒服，傍晚风景好；风大的日子注意保暖。', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000003', 'nippori-minami-park', '日暮里南公园', '日暮里南公園', 'park', '荒川区', 35.7257, 139.7752, '東京都荒川区東日暮里5丁目19', '日暮里站', 1, 8, false, false, true, 4, 2, 1, 3, '车站附近的小型公园，适合顺路短暂停留，给孩子跑一跑、滑一滑。', '空间不算大，更适合饭前饭后的短时间放电。', 'https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000004', 'tenno-park', '天王公园', '天王公園', 'park', '荒川区', 35.7339, 139.7908, '東京都荒川区南千住6丁目67', '南千住站', 1, 9, false, false, true, 4, 2, 2, 4, '社区型公园，游具和开放空间平衡，适合附近家庭日常遛娃。', '下午人会多，低龄宝宝建议避开大孩子集中的时段。', 'https://images.unsplash.com/photo-1518156677180-95a2893f3499?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000005', 'ogunohara-park', '尾久之原公园', '尾久の原公園', 'park', '荒川区', 35.7515, 139.7747, '東京都荒川区东尾久7丁目1', '熊野前站', 0, 10, false, false, true, 5, 3, 2, 4, '以广阔草地和蜻蜓池闻名，节奏舒缓，很适合野餐和自然观察。", "tips": "草地面积大，带野餐垫体验更好；雨后部分区域会泥泞。', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000006', 'yuinomori-arakawa', 'ゆいの森荒川', 'ゆいの森あらかわ', 'library', '荒川区', 35.7364, 139.7819, '東京都荒川区荒川2丁目50-1', '荒川二丁目站', 0, 10, true, true, true, 5, 5, 2, 3, '图书馆、儿童空间和学习设施结合的亲子友好室内去处，雨天非常实用。', '低龄区安静舒适，适合雨天续航；注意馆内饮食规则。', 'https://images.unsplash.com/photo-1521587760476-6c12a4b040da?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000007', 'arakawa-yuen', '荒川游园', 'あらかわ遊園', 'indoor_play', '荒川区', 35.7513, 139.7588, '東京都荒川区西尾久6丁目35-11', '荒川游园地前站', 1, 8, false, false, false, 4, 4, 3, 5, '复古亲子游乐园，设施温和，对幼儿 and 小学低年级很友好。', '热门项目可能排队，建议提前确认营业日和门票规则。', 'https://images.unsplash.com/photo-1502136969935-8d8eef54d77b?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000008', 'asukayama-park', '飞鸟山公园', '飛鳥山公園', 'park', '北区', 35.7509, 139.7382, '東京都北区王子1丁目1-3', '王子站', 0, 10, false, false, true, 4, 3, 2, 5, '有大型游具、火车展示和季节花景，是北区代表性的亲子公园。', '小山坡较多，婴儿车建议走缓坡路线；樱花季人流很大。', 'https://images.unsplash.com/photo-1522383225653-ed111181a951?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000009', 'ueno-zoo', '上野动物园', '上野動物園', 'zoo', '台东区', 35.7167, 139.7714, '東京都台东区上野公园9-83', '上野站', 1, 10, false, false, false, 4, 4, 2, 5, '东京经典动物园，动物种类丰富，适合安排半天到一天。', '园区大，提前定好重点路线；午后低龄孩子容易累。', 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000010', 'ueno-park', '上野恩赐公园', '上野恩賜公園', 'park', '台东区', 35.7148, 139.7735, '東京都台东区上野公园', '上野站', 0, 10, false, false, true, 4, 3, 2, 4, '公园、美术馆、动物园和池塘集中，适合按天气灵活组合行程。', '周末人多，带娃建议早到；可和动物园或博物馆搭配。', 'https://images.unsplash.com/photo-1557409518-691ebcd96038?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000011', 'hibiya-park', '日比谷公园', '日比谷公園', 'park', '千代田区', 35.6738, 139.7558, '東京都千代田区日比谷公園', '日比谷站', 0, 10, false, false, true, 5, 4, 3, 4, '市中心的绿洲，有大型喷泉、儿童游具和草坪，交通极其便利。', '适合逛完银座后来这里放电；游具区维护很好，适合幼儿。', 'https://images.unsplash.com/photo-1596464716127-f2a82984de30?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000012', 'shiba-park', '芝公园', '芝公園', 'park', '港区', 35.6554, 139.7484, '東京都港区芝公园4丁目', '御成门站 / 芝公园站', 0, 10, false, false, true, 5, 3, 2, 4, '就在东京塔脚下，草坪非常宽大，是带孩子和东京塔合影、野餐的最佳地点。', '带上野餐垫，欣赏最美的东京塔景色；周边咖啡馆很多。', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000013', 'shinjuku-gyoen', '新宿御苑', '新宿御苑', 'park', '新宿区', 35.6852, 139.7101, '東京都新宿区内藤町11', '新宿御苑前站', 0, 10, false, false, false, 5, 4, 1, 4, '超大型皇室园林，草坪极其平整，没有酒精和球类干扰，对婴幼儿极度友好。', '需购票进入，但非常干净安全。适合练习走路的宝宝和野餐家庭。', 'https://images.unsplash.com/photo-1578469645742-46cae010e5d3?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000014', 'yoyogi-park', '代代木公园', '代々木公園', 'park', '涩谷区', 35.6717, 139.6949, '東京都渋谷区代々木神園町2-1', '原宿站 / 代代木公园站', 0, 10, false, false, true, 4, 3, 2, 5, '深受家庭喜爱的森林公园，有专门的自行车赛道和极大的奔跑空间。', '周末常有活动和市集；可以租亲子自行车骑行。', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000015', 'kasai-rinkai-park', '葛西临海公园', '葛西臨海公園', 'park', '江户川区', 35.6366, 139.8585, '東京都江戸川区臨海町6丁目', '葛西临海公园站', 0, 10, false, false, true, 5, 4, 5, 5, '海边巨型公园，有大摩天轮、水族馆和人造沙滩，可以玩一整天。', '水族馆性价比极高；夏天的海风很舒服，但要注意防晒。', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000016', 'miraikan', '科学未来馆', '日本科学未来館', 'science_museum', '江东区', 35.6193, 139.7766, '東京都江東区青海2丁目3-6', '台场海滨公园站', 3, 12, true, true, false, 5, 5, 4, 4, '高科技互动博物馆，可以看到著名的机器人 ASIMO 和巨大的地球模型。', '三楼的儿童乐园（Curiosity Field）非常适合低龄孩子探索。', 'https://images.unsplash.com/photo-1518152177441-df00ee12f22e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000017', 'kinuta-park', '砧公园', '砧公園', 'park', '世田谷区', 35.63, 139.6174, '東京都世田谷区砧公園1-1', '用贺站', 0, 10, false, false, true, 5, 4, 4, 5, '拥有著名的“众人的广场”，是一个全包容性游乐场，所有身体机能的孩子都能一起玩。', '草地面积惊人，是世田谷区居民最爱的公园；春天赏樱胜地。', 'https://images.unsplash.com/photo-1496412705862-e0088f16f791?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000018', 'hikarigaoka-park', '光之丘公园', '光が丘公園', 'park', '练马区', 35.7616, 139.63, '東京都練馬区光が丘4丁目1-1', '光之丘站', 0, 10, false, false, true, 4, 3, 4, 4, '练马区最大的公园，有一条非常壮观的银杏大道和巨大的儿童游乐区。", "tips": "秋天看银杏绝美，夏天有水池喷泉可以玩水。', 'https://images.unsplash.com/photo-1502082553048-f009c37129b9?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000019', 'tokyo-dome-city', '东京巨蛋城', '東京ドームシティ', 'indoor_play', '文京区', 35.7056, 139.7519, '東京都文京区後楽1丁目3-61', '后乐园站 / 水道桥站', 1, 10, true, true, true, 5, 5, 4, 5, '集游乐园、商业、餐厅于一体。核心推荐“Asobono”室内游乐场，是东京规模最大、设施最全的室内乐园之一。', 'Asobono 周末人非常多，建议一开门就进。雨天续航神器。', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000020', 'mizumoto-park', '水元公园', '水元公園', 'park', '葛饰区', 35.7877, 139.8703, '東京都葛飾区水元公園3-2', '金町站', 0, 10, false, false, true, 3, 2, 5, 5, '东京都内唯一拥有水乡景观的公园，感觉像到了江南。空间极其开阔，树林茂密。', '地理位置偏，更适合自驾；带上帐篷可以玩一整天，有很多探险小路。', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000021', 'itabsashi-children-zoo', '板桥子儿童动物园', '板橋区立こども動物園', 'zoo', '板桥区', 35.7516, 139.7093, '東京都板橋区板橋3丁目50-1', '板桥区役所前站', 0, 6, false, false, true, 4, 4, 2, 3, '免费的社区型动物园，可以摸羊驼、骑小马，非常干净且温馨。', '适合学步期和学龄前儿童，羊驼非常温顺，可以和它们零距离接触。', 'https://images.unsplash.com/photo-1533630666687-9bb32d96924d?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000022', 'mabashi-park', '马桥公园', '馬橋公園', 'park', '杉并区', 35.7061, 139.6455, '東京都杉並区高円寺北4丁目35-5', '阿佐谷站', 1, 8, false, false, true, 4, 2, 1, 4, '当地家庭非常喜爱的公园，有大片的树荫和戏水区，氛围非常悠闲。', '高圆寺、阿佐谷一带的家长都爱带孩子来这，可以顺便逛逛周边可爱的店。', 'https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000023', 'nakano-central-park', '中野中央公园', '中野セントラルパーク', 'park', '中野区', 35.7077, 139.6601, '東京都中野区中野4丁目10-2', '中野站', 0, 10, false, false, true, 5, 4, 3, 4, '新型商业开发区域的绿地，周围全是餐厅和咖啡。孩子在前面的喷泉或草坪玩，家长在旁边喝咖啡，非常现代。', '夏天喷泉会有很多小朋友玩水；周边吃喝非常方便，即使是午餐时间也不愁没地方坐。', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000024', 'heiwa-no-mori-park', '平和之森公园', '平和の森公園', 'park', '大田区', 35.5815, 139.7408, '東京都大田区平和の森公園2-1', '平和岛站', 4, 12, false, false, false, 3, 3, 4, 5, '拥有东京最好的户外田径场（Athletics field），40多个挑战项目，非常适合训练大一点的孩子在丛林里攀爬。', '田径场需要穿运动鞋且买票进入（360日元）。不适合太小的宝宝，会比较耗体力。', 'https://images.unsplash.com/photo-1547407139-3c921a66005c?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000025', 'hamacho-park', '滨町公园', '浜町公園', 'park', '中央区', 35.6874, 139.7877, '東京都中央区日本橋浜町2丁目59-1', '滨町站 / 水天宫前站', 0, 10, false, false, true, 4, 3, 2, 4, '中央区内规模较大的公园，游具非常新，就在隅田川边，视野开阔。', '旁边就是著名的甜点店和日本桥街道，推荐作为城市Citywalk的一站。', 'https://images.unsplash.com/photo-1505069446780-4ef442b5207f?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000026', 'sunshine-aquarium', '阳光水族馆', 'サンシャイン水族館', 'aquarium', '丰岛区', 35.7288, 139.7191, '東京都豊島区東池袋3丁目1-3', '东池袋站 / 池袋站', 0, 12, true, true, false, 5, 5, 4, 4, '城市高空水族馆，著名的“天空企鹅”让人感觉企鹅在池袋的高楼大厦间游泳。', '即使池袋人很多，这里对推车家庭的便利设施做得非常好。建议平日错峰来。', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000027', 'shinagawa-aquarium', '品川水族馆', 'しながわ水族館', 'aquarium', '品川区', 35.5878, 139.736, '東京都品川区勝島3丁目2-1', '大森海岸站', 0, 10, true, true, false, 4, 4, 3, 4, '老牌水族馆，就在平和岛附近。相比新潮水族馆，这里的海洋表演和隧道更有亲切感。', '门票价格相对亲民；馆内虽老但很温馨，适合小宝宝第一站。', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000028', 'rinshi-no-mori-park', '林试之森公园', '林試の森公園', 'park', '目黑区', 35.6237, 139.6998, '東京都目黒区下目黒5丁目', '武蔵小山站', 1, 10, false, false, true, 4, 2, 1, 5, '以前是苗圃，所以树种非常丰富。感觉像是在原始森林里，夏天非常凉快。', '夏天要注意防蚊；武藏小山有著名的商业街，玩累了去步行街吃饭非常舒服。', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000029', 'inokashira-park', '井之头恩赐公园', '井の頭恩賜公園', 'park', '三鹰市', 35.7001, 139.573, '東京都三鷹市下連雀1丁目1', '吉祥寺站', 0, 10, false, false, true, 4, 4, 2, 5, '跨越武藏野市和三鹰市（紧邻23区）。除了天鹅船，还有个小小动物园，吉卜力美术馆也在旁边。', '必去吉祥寺逛街带娃路线；环境非常治愈，春天一定要来划船看樱花。', 'https://images.unsplash.com/photo-1502082553048-f009c37129b9?auto=format&fit=crop&w=1200&q=80'),
('10000000-0000-4000-8000-000000000030', 'sumida-aquarium-2', '墨田水族馆', 'すみだ水族館', 'aquarium', '墨田区', 35.7101, 139.8107, '東京都墨田区押上1丁目1-2', '押上站', 0, 10, true, true, false, 5, 5, 4, 3, '城市精品水族馆，以漂亮的水母和巨大的室内企鹅池著称。', '和晴空塔绑定行程；非常适合推车家庭，空间紧凑不累。', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80')
on conflict (id) do update set
  slug = excluded.slug,
  name_zh = excluded.name_zh,
  name_ja = excluded.name_ja,
  category = excluded.category,
  ward = excluded.ward,
